      return Math.max(0, Number(localStorage.getItem(STORAGE_KEY)) || 0);
    } catch {
      return 0;
    }
  }

  function saveBest(value) {
    try {
      localStorage.setItem(STORAGE_KEY, String(Math.round(value)));
    } catch {
      /* private mode */
    }
  }

  function loadSound() {
    try {
      return localStorage.getItem(SOUND_KEY) !== 'off';
    } catch {
      return true;
    }
  }

  function saveSound(enabled) {
    try {
      localStorage.setItem(SOUND_KEY, enabled ? 'on' : 'off');
    } catch {
      /* private mode */
    }
  }

  const state = {
    mode: 'start',
    time: 75,
    maxTime: 75,
    elapsed: 0,
    score: 0,
    combo: 1,
    comboTimer: 0,
    bestCombo: 1,
    scans: 0,
    misses: 0,
    spawnTimer: 1.2,
    decoyTimer: 3.4,
    shootTimer: 2.6,
    objects: [],
    particles: [],
    floaters: [],
    ripples: [],
    shootingStars: [],
    stars: [],
    twinkles: [],
    aim: {
      x: 0,
      y: 0,
      tx: 0,
      ty: 0,
      active: false,
      touch: false,
      fingerX: 0,
      fingerY: 0,
      fingerLife: 0
    },
    scanTarget: null,
    scanProgress: 0,
    decoyTarget: null,
    shake: 0,
    flash: 0,
    flashRGB: [255, 110, 100],
    lastSecond: 75,
    moon: { x: 0, y: 0, r: 40 }
  };

  let W = 0;
  let H = 0;
  let DPR = 1;
  let bgCanvas = null;
  let fgCanvas = null;
  let lastFrame = 0;
  let resizeQueued = false;
  let statusTimer = 0;
  let hintTimer = 0;
  let endShowTimer = 0;
  let best = loadBest();

  const keys = new Set();

  /* ------------------------------------------------------------------ */
  /* Audio                                                               */
  /* ------------------------------------------------------------------ */

  class SoundEngine {
    constructor() {
      this.ctx = null;
      this.master = null;
      this.scanOsc = null;
      this.scanGain = null;
      this.enabled = loadSound();
      this.scanOn = false;
    }

    init() {
      if (this.ctx) {
        this.resume();
        return;
      }
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      try {
        const audio = new AudioContext();
        this.ctx = audio;
        this.master = audio.createGain();
        this.master.gain.value = this.enabled ? 0.42 : 0;
        this.master.connect(audio.destination);
        this.buildAmbient();
        this.buildScanner();
      } catch {
        this.ctx = null;
      }
    }

    buildAmbient() {
      const c = this.ctx;
      if (!c) return;
      const pad = c.createGain();
      pad.gain.value = 0.026;
      pad.connect(this.master);

      const filter = c.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 360;
      filter.Q.value = 0.7;
      filter.connect(pad);

      const frequencies = [55, 82.41, 110];
      frequencies.forEach((freq, index) => {
        const osc = c.createOscillator();
        osc.type = index === 0 ? 'sine' : 'triangle';
        osc.frequency.value = freq;
        const gain = c.createGain();
        gain.gain.value = index === 0 ? 0.55 : 0.16;
        osc.connect(gain);
        gain.connect(filter);
        osc.start();
      });

      const lfo = c.createOscillator();
      lfo.frequency.value = 0.045;
      const lfoGain = c.createGain();
      lfoGain.gain.value = 120;
      lfo.connect(lfoGain);
      lfoGain.connect(filter.frequency);
      lfo.start();
    }

    buildScanner() {
      const c = this.ctx;
      if (!c) return;
      const osc = c.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = 200;
      const gain = c.createGain();
      gain.gain.value = 0;
      osc.connect(gain);
      gain.connect(this.master);
      osc.start();
      this.scanOsc = osc;
      this.scanGain = gain;
    }

    resume() {
      if (this.ctx && this.ctx.state === 'suspended') {
        this.ctx.resume().catch(() => {});
      }
    }

    suspend() {
      if (this.ctx && this.ctx.state === 'running') {
        this.ctx.suspend().catch(() => {});
      }
    }

    setEnabled(enabled) {
      this.enabled = enabled;
      saveSound(enabled);
      dom.soundBtn.setAttribute('aria-pressed', String(enabled));
      dom.soundBtn.setAttribute('aria-label', enabled ? 'Ton ausschalten' : 'Ton einschalten');
      if (!this.ctx) return;
      this.resume();
      const t = this.ctx.currentTime;
      this.master.gain.cancelScheduledValues(t);
      this.master.gain.setTargetAtTime(enabled ? 0.42 : 0, t, 0.06);
    }

    toggle() {
      this.init();
      this.setEnabled(!this.enabled);
    }

    scan(progress, active) {
      if (!this.ctx || !this.enabled) return;
      const t = this.ctx.currentTime;
      if (this.scanOn !== active) {
        this.scanOn = active;
        this.scanGain.gain.setTargetAtTime(active ? 0.022 : 0, t, active ? 0.03 : 0.07);
      }
      if (active) {
        this.scanOsc.frequency.setTargetAtTime(190 + progress * 330, t, 0.035);
      }
    }

    blip(freq = 880, duration = 0.07, volume = 0.06, type = 'sine') {
      if (!this.ctx || !this.enabled) return;
      const c = this.ctx;
      const t = c.currentTime;
      const osc = c.createOscillator();
      const gain = c.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, t);
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(volume, t + 0.008);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
      osc.connect(gain);
      gain.connect(this.master);
      osc.start(t);
      osc.stop(t + duration + 0.03);
    }

    success() {
      if (!this.ctx || !this.enabled) return;
      const c = this.ctx;
      const t = c.currentTime;
      [523.25, 783.99, 1046.5].forEach((freq, index) => {
        const start = t + index * 0.075;
        const osc = c.createOscillator();
        const gain = c.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(freq, start);
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(0.07, start + 0.012);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.52);
        osc.connect(gain);
        gain.connect(this.master);
        osc.start(start);
        osc.stop(start + 0.56);
      });
    }

    fail() {
      if (!this.ctx || !this.enabled) return;
      const c = this.ctx;
      const t = c.currentTime;
      const osc = c.createOscillator();
      const gain = c.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(165, t);
      osc.frequency.exponentialRampToValueAtTime(62, t + 0.3);
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(0.045, t + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.34);
      osc.connect(gain);
      gain.connect(this.master);
      osc.start(t);
      osc.stop(t + 0.38);
    }

    tick() {
      this.blip(1240, 0.035, 0.025, 'sine');
    }

    finish() {
      if (!this.ctx || !this.enabled) return;
      const c = this.ctx;
      const t = c.currentTime;
      [392, 523.25, 659.25, 783.99].forEach((freq, index) => {
        const start = t + index * 0.12;
        const osc = c.createOscillator();
        const gain = c.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, start);
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(0.045, start + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.9);
        osc.connect(gain);
        gain.connect(this.master);
        osc.start(start);
        osc.stop(start + 0.95);
      });
    }
  }

  const sound = new SoundEngine();

  /* __NEXT__ */
})();

